mapper.select:
SELECT 
FROM group_batch_task_item
WHERE task_id = #{taskId}
  AND status = #{waitingStatus}
  AND result_deadline_at IS NOT NULL
  AND result_deadline_at <= #{now}
ORDER BY result_deadline_at ASC, id ASC
LIMIT #{limit}

